<script setup lang="ts">
import { computed,nextTick,ref,watch } from 'vue'
import { payslipPostedLabel } from '~~/shared/utils/payslipPresentation'
const props=withDefaults(defineProps<{request:any;viewer?:'employee'|'staff';compact?:boolean}>(),{viewer:'employee'})
const conversation=ref<HTMLElement|null>(null)
const own=(message:any)=>message.Sender===(props.viewer==='staff'?'Staff':'Employee')
const sender=(message:any)=>message.Sender==='Staff'?(message.StaffName?.trim()||'HR / Payroll'):(props.viewer==='employee'?'You':props.request.EmployeeName||'Employee')
const initials=(message:any)=>sender(message).split(/[\s,]+/).filter(Boolean).slice(0,2).map((word:string)=>word[0]).join('').toUpperCase()
const officerDetails=(message:any)=>[message.StaffRole,message.StaffDepartment].filter(Boolean).join(' / ')
const date=(value:string)=>{const instant=new Date(value);return Number.isFinite(instant.getTime())?instant.toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric',timeZone:'Asia/Singapore'}):''}
const time=(value:string)=>{const instant=new Date(value);return Number.isFinite(instant.getTime())?instant.toLocaleTimeString('en-PH',{hour:'numeric',minute:'2-digit',timeZone:'Asia/Singapore'}):''}
const messages=computed(()=>props.request.messages||[])
watch(()=>[props.request.RequestID,messages.value.length],async()=>{await nextTick();if(conversation.value)conversation.value.scrollTop=conversation.value.scrollHeight},{immediate:true})
</script>
<template>
 <section class="request-thread" :class="{compact}" aria-label="Request conversation">
  <header class="thread-heading"><div><p class="thread-kicker">REQUEST #{{request.RequestID}}</p><h4>{{request.FieldLabel}}</h4><small>Opened {{payslipPostedLabel(request.CreatedAt)}}</small></div><span class="thread-status" :class="{resolved:request.Status==='Resolved',closed:['Cancelled','Declined'].includes(request.Status)}">{{request.Status}}</span></header>
  <details class="correction-context" :open="!compact"><summary>Correction details <span>Recorded &amp; requested values</span></summary><dl><div><dt>Recorded when requested</dt><dd>{{request.RecordedValue||'Not recorded'}}</dd></div><div class="proposed"><dt>Requested correction</dt><dd>{{request.ProposedValue}}</dd></div></dl></details>
  <div class="conversation-title"><span>Conversation</span><small>{{messages.length}} message{{messages.length===1?'':'s'}}</small></div>
  <div ref="conversation" class="messages" role="log" aria-label="Messages with HR" aria-live="polite" aria-relevant="additions" tabindex="0">
   <template v-for="(message,index) in messages" :key="message.MessageID">
    <div v-if="index===0||date(message.CreatedAt)!==date(messages[index-1].CreatedAt)" class="message-day"><span>{{date(message.CreatedAt)}}</span></div>
    <article class="message-row" :class="{own:own(message),staff:message.Sender==='Staff'}" :aria-label="'Message from '+sender(message)"><span class="message-avatar" aria-hidden="true">{{initials(message)}}</span><div class="message-content"><header><strong>{{sender(message)}}</strong><span v-if="message.Sender==='Staff'" class="officer-details">{{officerDetails(message)||'HR / Payroll'}}</span></header><div class="message-bubble"><p>{{message.Message}}</p></div><footer><time :datetime="message.CreatedAt" :title="payslipPostedLabel(message.CreatedAt)">{{time(message.CreatedAt)}}</time><span v-if="message.Status" class="message-status">{{message.Status}}</span></footer></div></article>
   </template>
   <p v-if="!messages.length" class="no-messages">No messages in this request yet.</p>
  </div>
  <div v-if="$slots.composer" class="message-composer"><slot name="composer"/></div>
 </section>
</template>
<style scoped>
